<script>
(function(){
const form=document.getElementById('contact-form');
const status=document.getElementById('contact-status');
const send=document.getElementById('send-button');const copy=document.getElementById('copy-button');
const whatsappPhone='51983738087';
send.disabled=false;copy.disabled=false;
function prepare(){
 const name=form.elements.nombre;const message=form.elements.mensaje;
 name.setCustomValidity(name.value.trim()?'':'Escribe tu nombre.');
 message.setCustomValidity(message.value.trim().length>=10?'':'Escribe un mensaje de al menos 10 caracteres.');
 if(!form.reportValidity())return null;
 return {body:'*Contacto DDP*\n\nNombre: '+name.value.trim()+'\nCorreo: '+form.elements.correo.value.trim()+'\nMotivo: '+form.elements.motivo.value+'\n\nMensaje:\n'+message.value.trim()};
}
form.addEventListener('input',e=>{if(e.target.setCustomValidity)e.target.setCustomValidity('');});
form.addEventListener('submit',e=>{e.preventDefault();const data=prepare();if(!data)return;const whatsappUrl='https://web.whatsapp.com/send?phone='+whatsappPhone+'&text='+encodeURIComponent(data.body);window.open(whatsappUrl,'_blank','noopener,noreferrer');status.textContent='WhatsApp Web se abrió con el mensaje preparado. Revísalo y pulsa Enviar para completar el envío.';});
copy.addEventListener('click',async()=>{const data=prepare();if(!data)return;try{await navigator.clipboard.writeText(data.body);status.textContent='Mensaje copiado. Puedes pegarlo en WhatsApp Web.';}catch(error){status.textContent='No se pudo copiar automáticamente. Selecciona y copia el texto de tu mensaje.';form.elements.mensaje.focus();form.elements.mensaje.select();}});
})();
</script></body></html>
